/* eslint-disable space-in-parens */

import Complex64Array = require( '@stdlib/array/complex64' );
import Memory = require( '@stdlib/wasm/memory' );
import scasum = require( './index' );


// TESTS //

// Attached to the main export is a `main` method which returns a number...
{
	const cx = new Complex64Array( 10 );

	scasum.main( cx.length, cx, 1 ); // $ExpectType number
}

// The compiler throws an error if the `main` method is provided a first argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	scasum.main( '10', cx, 1 ); // $ExpectError
	scasum.main( true, cx, 1 ); // $ExpectError
	scasum.main( false, cx, 1 ); // $ExpectError
	scasum.main( null, cx, 1 ); // $ExpectError
	scasum.main( undefined, cx, 1 ); // $ExpectError
	scasum.main( [], cx, 1 ); // $ExpectError
	scasum.main( {}, cx, 1 ); // $ExpectError
	scasum.main( ( cx: number ): number => cx, cx, 1 ); // $ExpectError
}

// The compiler throws an error if the `main` method is provided a second argument which is not a Complex64Array...
{
	const cx = new Complex64Array( 10 );

	scasum.main( cx.length, 10, 1 ); // $ExpectError
	scasum.main( cx.length, '10', 1 ); // $ExpectError
	scasum.main( cx.length, true, 1 ); // $ExpectError
	scasum.main( cx.length, false, 1 ); // $ExpectError
	scasum.main( cx.length, null, 1 ); // $ExpectError
	scasum.main( cx.length, undefined, 1 ); // $ExpectError
	scasum.main( cx.length, [], 1 ); // $ExpectError
	scasum.main( cx.length, {}, 1 ); // $ExpectError
	scasum.main( cx.length, ( cx: number ): number => cx, 1 ); // $ExpectError
}

// The compiler throws an error if the `main` method is provided a third argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	scasum.main( cx.length, cx, '10' ); // $ExpectError
	scasum.main( cx.length, cx, true ); // $ExpectError
	scasum.main( cx.length, cx, false ); // $ExpectError
	scasum.main( cx.length, cx, null ); // $ExpectError
	scasum.main( cx.length, cx, undefined ); // $ExpectError
	scasum.main( cx.length, cx, [] ); // $ExpectError
	scasum.main( cx.length, cx, {} ); // $ExpectError
	scasum.main( cx.length, cx, ( cx: number ): number => cx ); // $ExpectError
}

// The compiler throws an error if the `main` method is provided an unsupported number of arguments...
{
	const cx = new Complex64Array( 10 );

	scasum.main(); // $ExpectError
	scasum.main( cx.length ); // $ExpectError
	scasum.main( cx.length, cx ); // $ExpectError
	scasum.main( cx.length, cx, 1, 10 ); // $ExpectError
}

// Attached to main export is an `ndarray` method which returns a number...
{
	const cx = new Complex64Array( 10 );

	scasum.ndarray( cx.length, cx, 1, 0 ); // $ExpectType number
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	scasum.ndarray( '10', cx, 1, 0 ); // $ExpectError
	scasum.ndarray( true, cx, 1, 0 ); // $ExpectError
	scasum.ndarray( false, cx, 1, 0 ); // $ExpectError
	scasum.ndarray( null, cx, 1, 0 ); // $ExpectError
	scasum.ndarray( undefined, cx, 1, 0 ); // $ExpectError
	scasum.ndarray( [], cx, 1, 0 ); // $ExpectError
	scasum.ndarray( {}, cx, 1, 0 ); // $ExpectError
	scasum.ndarray( ( cx: number ): number => cx, cx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a Complex64Array...
{
	const cx = new Complex64Array( 10 );

	scasum.ndarray( cx.length, 10, 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, '10', 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, true, 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, false, 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, null, 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, undefined, 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, [], 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, {}, 1, 0 ); // $ExpectError
	scasum.ndarray( cx.length, ( cx: number ): number => cx, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	scasum.ndarray( cx.length, cx, '10', 0 ); // $ExpectError
	scasum.ndarray( cx.length, cx, true, 0 ); // $ExpectError
	scasum.ndarray( cx.length, cx, false, 0 ); // $ExpectError
	scasum.ndarray( cx.length, cx, null, 0 ); // $ExpectError
	scasum.ndarray( cx.length, cx, undefined, 0 ); // $ExpectError
	scasum.ndarray( cx.length, cx, [], 0 ); // $ExpectError
	scasum.ndarray( cx.length, cx, {}, 0 ); // $ExpectError
	scasum.ndarray( cx.length, cx, ( cx: number ): number => cx, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const cx = new Complex64Array( 10 );

	scasum.ndarray( cx.length, cx, 1, '10' ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, true ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, false ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, null ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, undefined ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, [] ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, {} ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, ( cx: number ): number => cx ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const cx = new Complex64Array( 10 );

	scasum.ndarray(); // $ExpectError
	scasum.ndarray( cx.length ); // $ExpectError
	scasum.ndarray( cx.length, cx ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1 ); // $ExpectError
	scasum.ndarray( cx.length, cx, 1, 0, 10 ); // $ExpectError
}

// Attached to the main export is a `Module` constructor which returns a module...
{
	const mem = new Memory({
		'initial': 0
	});

	scasum.Module( mem ); // $ExpectType Module
}

// The compiler throws an error if the `Module` constructor is not provided a WebAssembly memory instance...
{
	scasum.Module( '10' ); // $ExpectError
	scasum.Module( true ); // $ExpectError
	scasum.Module( false ); // $ExpectError
	scasum.Module( null ); // $ExpectError
	scasum.Module( undefined ); // $ExpectError
	scasum.Module( [] ); // $ExpectError
	scasum.Module( {} ); // $ExpectError
	scasum.Module( ( cx: number ): number => cx ); // $ExpectError
}

// The `Module` constructor returns a module instance having a `main` method which returns a number...
{
	const mem = new Memory({
		'initial': 1
	});
	const mod = scasum.Module( mem );

	mod.main( 10, 0, 1 ); // $ExpectType number
}

// The compiler throws an error if the `main` method of a module instance is provided a first argument which is not a number...
{
	const mem = new Memory({
		'initial': 1
	});
	const mod = scasum.Module( mem );

	mod.main( '10', 0, 1 ); // $ExpectError
	mod.main( true, 0, 1 ); // $ExpectError
	mod.main( false, 0, 1 ); // $ExpectError
	mod.main( null, 0, 1 ); // $ExpectError
	mod.main( undefined, 0, 1 ); // $ExpectError
	mod.main( [], 0, 1 ); // $ExpectError
	mod.main( {}, 0, 1 ); // $ExpectError
	mod.main( ( cx: number ): number => cx, 0, 1 ); // $ExpectError
}

// The compiler throws an error if the `main` method of a module instance is provided a second argument which is not a number...
{
	const mem = new Memory({
		'initial': 1
	});
	const mod = scasum.Module( mem );

	mod.main( 10, '10', 1 ); // $ExpectError
	mod.main( 10, true, 1 ); // $ExpectError
	mod.main( 10, false, 1 ); // $ExpectError
	mod.main( 10, null, 1 ); // $ExpectError
	mod.main( 10, undefined, 1 ); // $ExpectError
	mod.main( 10, [], 1 ); // $ExpectError
	mod.main( 10, {}, 1 ); // $ExpectError
	mod.main( 10, ( cx: number ): number => cx, 1 ); // $ExpectError
}

// The compiler throws an error if the `main` method of a module instance is provided a third argument which is not a number...
{
	const mem = new Memory({
		'initial': 1
	});
	const mod = scasum.Module( mem );

	mod.main( 10, 0, '10' ); // $ExpectError
	mod.main( 10, 0, true ); // $ExpectError
	mod.main( 10, 0, false ); // $ExpectError
	mod.main( 10, 0, null ); // $ExpectError
	mod.main( 10, 0, undefined ); // $ExpectError
	mod.main( 10, 0, [] ); // $ExpectError
	mod.main( 10, 0, {} ); // $ExpectError
	mod.main( 10, 0, ( cx: number ): number => cx ); // $ExpectError
}

// The compiler throws an error if the `main` method of a module instance is provided an unsupported number of arguments...
{
	const mem = new Memory({
		'initial': 1
	});
	const mod = scasum.Module( mem );

	mod.main(); // $ExpectError
	mod.main( 10 ); // $ExpectError
	mod.main( 10, 0 ); // $ExpectError
	mod.main( 10, 0, 1, 10 ); // $ExpectError
}

// The `Module` constructor returns a module instance having an `ndarray` method which returns a number...
{
	const mem = new Memory({
		'initial': 1
	});
	const mod = scasum.Module( mem );

	mod.ndarray( 10, 0, 1, 0 ); // $ExpectType number
}

